import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    static final long MOD = 1000000007L;
    static final int MOD_TOTIENT = (int) (MOD - 1);

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        long[] factorial = new long[n + 1];
        factorial[0] = 1L;
        for (int j = 1; j <= n; j++) {
            factorial[j] = (j * factorial[j - 1]) % MOD;
        }
        long[] factInv = new long[n + 1];
        for (int i = 0; i <= n; i++) {
            factInv[i] = pow(factorial[i], -1);
        }

        java.util.function.BiFunction<Integer, Integer, Long> permute = (a, b) ->
                (factorial[a] * factInv[b]) % MOD;

        class Arranger {
            long arrange(int a, int b) {
                int here = n / a;
                int above = here / b;
                return ((here - above) * permute.apply(n - above - 1, n - here)) % MOD;
            }
        }

        Arranger arranger = new Arranger();

        int lg = 0;
        while ((1 << lg) <= n) {
            lg++;
        }
        lg--;
        long curr = 1L;
        for (int e = 0; e <= lg; e++) {
            curr *= arranger.arrange(1 << e, 2);
            curr %= MOD;
        }
        long answer = curr;
        if (n >= 3 * (1 << (lg - 1))) {
            for (int e = lg; e >= 1; e--) {
                curr *= pow(arranger.arrange(1 << e, 3), -1);
                curr %= MOD;
                curr *= arranger.arrange(3 * (1 << (e - 1)), 2);
                curr %= MOD;
                curr *= pow(arranger.arrange(1 << (e - 1), 2), -1);
                curr %= MOD;
                curr *= arranger.arrange(1 << (e - 1), 3);
                curr %= MOD;
                answer += curr;
            }
            answer %= MOD;
        }
        System.out.println(answer);
    }

    static long pow(long base, int power) {
        int e = power;
        e %= MOD_TOTIENT;
        if (e < 0) {
            e += MOD_TOTIENT;
        }
        if (e == 0 && base == 0L) {
            return base;
        }
        long b = base % MOD;
        long res = 1L;
        while (e > 0) {
            if ((e & 1) != 0) {
                res *= b;
                res %= MOD;
            }
            b *= b;
            b %= MOD;
            e >>= 1;
        }
        return res;
    }
}

